const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// ---- config (digest block, safe defaults) ----
let cfg = {};
try { cfg = JSON.parse((safeAll('Fetch Config').find(r => r && r.key === 'config_json') || {}).value || '{}'); } catch (e) { cfg = {}; }
const D = Object.assign({
  enabled: true, hot_score: 80, warm_score: 65, max_embeds: 8, post_when_empty: false,
  include_statuses: ['pending', 'approved', 'edited'],
  sheet_url: '', outreach_gid: ''
}, cfg.digest || {});

// one line, trimmed
const cut = (s, n) => { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 3) + '...' : s; };
const orDash = (s, n) => cut(s, n) || '-';
// keeps line breaks, for text you will copy. Shown in a code block so Discord gives it a copy button.
const block = (s, n) => {
  s = String(s == null ? '' : s).replace(/```/g, "'''").replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
  if (!s) return '-';
  if (s.length > n) s = s.slice(0, n - 3) + '...';
  return '```\n' + s + '\n```';
};
const nowIso = new Date().toISOString();

const stats = { queue_rows: 0, candidates: 0, embedded: 0, overflow: 0, pending_announced: 0, approved_announced: 0, skipped: '' };
const base = (extra) => ({ json: Object.assign({ __digest: true, has_items: false, payload: null, keys: [], stats, config_rev: cfg.rev || '', run_at: nowIso }, extra) });

if (D.enabled === false) { stats.skipped = 'digest disabled by config'; return [base({})]; }

const queue = safeAll('Fetch Outreach Queue').filter(r => r && r.outreach_id);
stats.queue_rows = queue.length;
const accounts = {}; for (const a of safeAll('Fetch Accounts')) if (a && a.account_id) accounts[String(a.account_id)] = a;
const contacts = {}; for (const c of safeAll('Fetch Contacts')) if (c && c.contact_id) contacts[String(c.contact_id)] = c;
const seen = new Set(safeAll('Fetch Digest Log').map(r => String(r && r.digest_key || '')).filter(Boolean));

const include = D.include_statuses.map(s => String(s).toLowerCase());
const cands = queue.filter(r => {
  const st = String(r.approval_status || '').toLowerCase();
  const sent = String(r.send_status || 'not_sent').toLowerCase();
  return include.includes(st) && sent === 'not_sent' && !seen.has(r.outreach_id + ':' + st);
}).map(r => {
  const a = accounts[String(r.account_id)] || {};
  return { r, a, c: contacts[String(r.contact_id)] || {}, st: String(r.approval_status).toLowerCase(), score: Number(a.final_score || 0) };
});
// approved first, then by account score
cands.sort((x, y) => (y.st === 'approved') - (x.st === 'approved') || y.score - x.score);
stats.candidates = cands.length;

if (!cands.length) {
  stats.skipped = 'nothing new to announce';
  if (D.post_when_empty === true) return [base({ has_items: true, payload: { username: 'GTM Engine', content: 'GTM digest: nothing new today. Queue rows: ' + queue.length + '.', allowed_mentions: { parse: [] } } })];
  return [base({})];
}

const link = (D.sheet_url && D.outreach_gid) ? String(D.sheet_url).replace(/\/edit.*$/, '') + '/edit#gid=' + D.outreach_gid : '';
const colorOf = s => s >= Number(D.hot_score) ? 5763719 : (s >= Number(D.warm_score) ? 16705372 : 9807270);
const LABEL = { approved: 'APPROVED', edited: 'EDITED', pending: 'REVIEW' };

// One full card per draft. Discord limits: 1024 chars per field, 6000 chars per message.
const embedOf = ({ r, a, c, st, score }) => {
  const f = [];
  const add = (name, value, inline) => f.push({ name, value, inline: inline === true });
  const tz = (a.timezone_utc_offset == null || a.timezone_utc_offset === '') ? '?' : ((Number(a.timezone_utc_offset) >= 0 ? '+' : '') + a.timezone_utc_offset);
  const li = String(c.linkedin_url || '').trim();
  const isEmail = String(r.channel || '').toLowerCase() === 'email';

  // --- who and why ---
  add('Account', orDash((a.industry || '-') + ' | ' + (a.employee_count || '?') + ' staff | UTC' + tz + ' | ' + (a.funding_stage || 'funding ?') + ' | ' + (a.domain || ''), 300));
  add('Contact', orDash((r.contact_name || '') + ', ' + (c.title || '?') + ' | score ' + (c.contact_score || '?') + (c.email ? ' | ' + c.email + ' (' + (c.email_status || '?') + ')' : ''), 300) + (li ? '\n' + li : ''));
  add('Why it matches', orDash(a.why_match, 300));
  if (String(a.tech_stack || '').trim()) add('Tech stack', orDash(a.tech_stack, 200));
  if (String(a.clay_summary || '').trim()) add('Company summary (Clay)', orDash(a.clay_summary, 500));

  // --- the strategy ---
  add('Angle', orDash(r.angle, 200));
  add('Trigger', orDash(r.trigger, 250));
  add('Pain point', orDash(r.pain_point, 250));
  add('Value proposition', orDash(r.value_proposition, 300));
  add('Proof point', orDash(r.proof_point, 250));

  // --- the text you send. The channel you will actually use comes first ---
  const note = () => add('LinkedIn note (' + String(r.linkedin_note || '').length + '/300 chars)', block(r.linkedin_note, 1000));
  const msg = () => {
    if (isEmail) add('Email subject', orDash(r.email_subject, 150));
    add(isEmail ? 'Email body' : 'Long message (after they accept, or InMail)', block(r.message_draft, 1000));
  };
  if (isEmail) { msg(); note(); } else { note(); msg(); }
  add('Follow-ups', '1) ' + orDash(r.follow_up_1, 300) + '\n2) ' + orDash(r.follow_up_2, 300) + '\n3) ' + orDash(r.follow_up_3, 300));

  add('Risk flags', orDash(r.risk_notes, 400));

  return {
    title: cut((LABEL[st] || 'REVIEW') + ' | ' + (a.company_name || r.company_name) + ' | ' + score, 250),
    // Deep link to this draft's row: lands on linkedin_note (T), risk_notes (U), approval_status (V)
    url: link ? link + (Number(r.row_number) > 1 ? '&range=T' + r.row_number + ':V' + r.row_number : '') : undefined,
    description: cut('Status: ' + st + ' | Channel: ' + (r.channel || '-') + ' | Provider: ' + (r.llm_provider || '-') + ' | Drafted: ' + String(r.run_date || '').slice(0, 10), 300),
    color: colorOf(score), fields: f,
    // The footer is the dedupe key. Expand Keys reads it back from Discord's reply, so do not change its shape.
    footer: { text: cut(r.outreach_id + ':' + st, 200) }
  };
};
const size = e => (e.title || '').length + (e.description || '').length + (e.footer ? e.footer.text.length : 0) + e.fields.reduce((s, x) => s + x.name.length + x.value.length, 0);

const maxCards = Math.min(10, Math.max(1, Number(D.max_embeds || 8)));
const picked = cands.slice(0, maxCards);
stats.embedded = picked.length;
stats.overflow = cands.length - picked.length;
stats.pending_announced = picked.filter(k => k.st !== 'approved').length;
stats.approved_announced = picked.filter(k => k.st === 'approved').length;

const header = '**GTM digest** | ' + stats.pending_announced + ' to review, ' + stats.approved_announced + ' approved (send manually). Nothing is sent automatically.' +
  (stats.overflow ? ' ' + stats.overflow + ' more will appear in the next digest.' : '');

// One Discord message per draft, so a full card never hits the 6000-char message limit.
return picked.map((cnd, i) => {
  const e = embedOf(cnd);
  // Safety net: if a card is still too big, shorten the long message first.
  let guard = 0;
  while (size(e) > 5600 && guard++ < 5) {
    const big = e.fields.slice().sort((x, y) => y.value.length - x.value.length)[0];
    big.value = big.value.slice(0, Math.max(200, big.value.length - 400)).replace(/`+$/, '') + (big.value.startsWith('```') ? '...\n```' : '...');
  }
  const content = (i === 0 ? header + '\n' : '') + '**' + (i + 1) + '/' + picked.length + '** ' + cut(cnd.r.contact_name + ' at ' + (cnd.a.company_name || cnd.r.company_name), 150);
  return base({
    has_items: true,
    keys: [{ digest_key: cnd.r.outreach_id + ':' + cnd.st, outreach_id: cnd.r.outreach_id, status: cnd.st, announced_at: nowIso }],
    payload: { username: 'GTM Engine', content: content.slice(0, 1900), embeds: [e], allowed_mentions: { parse: [] } }
  });
});

// Reads the dedupe key back from each message Discord accepted (the embed footer).
// Only drafts that were really posted are remembered, so a failed post is retried next run.
const seen = new Set();
const out = [];
const now = new Date().toISOString();
for (const it of $input.all()) {
  for (const e of (((it.json || {}).embeds) || [])) {
    const key = String((e.footer || {}).text || '').trim();
    const m = key.match(/^(.+):([a-z_]+)$/);
    if (!m || seen.has(key)) continue;
    seen.add(key);
    out.push({ json: { digest_key: key, outreach_id: m[1], status: m[2], announced_at: now } });
  }
}
if (out.length) return out;
// Fallback if Discord's reply had no embeds: use the keys Build Digest prepared.
return $('Build Digest').all().flatMap(i => ((i.json || {}).keys || []).map(k => ({ json: k })));

const b = (() => { try { return $('Build Digest').first().json; } catch (e) { return {}; } })();
const s = b.stats || {};
const first = ($input.first() || { json: {} }).json || {};
let status = 'quiet';
let err = '';
if (b.has_items) {
  if (first.digest_key) status = 'sent';
  else {
    status = 'failed';
    const e = first.error;
    const msg = typeof e === 'string' ? e : ((e && (e.message || e.description)) || first.message || 'discord post failed');
    err = String(msg).slice(0, 200);
  }
}
if (!b.has_items && s.skipped) err = s.skipped;
return [{ json: {
  run_at: b.run_at || new Date().toISOString(),
  config_rev: b.config_rev || '',
  queue_rows: s.queue_rows || 0,
  candidates: s.candidates || 0,
  embedded: s.embedded || 0,
  overflow: s.overflow || 0,
  pending_announced: s.pending_announced || 0,
  approved_announced: s.approved_announced || 0,
  discord_status: status,
  error_sample: err
} }];
